import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int limit = sc.nextInt();

        int g = gcd(a, b);
        a /= g;
        b /= g;

        long x = 0, best_x = 0;
        int best_y = 1;
        double factor = 1.0, epsilon = 1e-10;

        for (int y = 1; y <= limit; y++) {
            while (Math.abs(factor * a / (double) b - factor * x / (double) y) > Math.abs(factor * a / (double) b - factor * (x + 10000) / (double) y)) {
                x += 10000;
            }
            while (Math.abs(factor * a / (double) b - factor * x / (double) y) + epsilon > Math.abs(factor * a / (double) b - factor * (x + 1) / (double) y)) {
                x++;
            }
            double currentDiff = Math.abs(factor * a / (double) b - factor * x / (double) y);
            double bestDiff = Math.abs(factor * a / (double) b - factor * best_x / (double) best_y);
            if (currentDiff < bestDiff) {
                best_x = x;
                best_y = y;
            }
        }

        long numerator = Math.max(0L, best_x - (b == 2 && best_x != a ? 1 : 0));
        System.out.println(numerator + "/" + best_y);
        sc.close();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
